-- Generated by generate_skill_affixes.py. Resolve incomplete group rolls once.
-- Keep item GUID, sequence, value, range, kind and rerolled flag unchanged.
-- A stable per-item/sequence hash chooses the missing skill; reruns are no-ops.
UPDATE dc_item_affix a JOIN item_instance i ON i.guid=a.item_guid JOIN characters c ON c.guid=i.owner_guid SET a.affix_id=ELT(1+MOD(CRC32(CONCAT(a.item_guid,':',a.seq,':skill-repair-v1')),4),'skill_barbarian_ancientspear','skill_barbarian_hammeroftheancients','skill_barbarian_whirlwind','skill_barbarian_seismicslam') WHERE c.class=1 AND a.affix_id='skill_head';
UPDATE dc_item_affix a JOIN item_instance i ON i.guid=a.item_guid JOIN characters c ON c.guid=i.owner_guid SET a.affix_id=ELT(1+MOD(CRC32(CONCAT(a.item_guid,':',a.seq,':skill-repair-v1')),7),'skill_barbarian_furiouscharge','skill_barbarian_avalanche','skill_barbarian_earthquake','skill_barbarian_rend','skill_barbarian_revenge','skill_barbarian_overpower','skill_barbarian_calloftheancients') WHERE c.class=1 AND a.affix_id='skill_torso';
UPDATE dc_item_affix a JOIN item_instance i ON i.guid=a.item_guid JOIN characters c ON c.guid=i.owner_guid SET a.affix_id=ELT(1+MOD(CRC32(CONCAT(a.item_guid,':',a.seq,':skill-repair-v1')),4),'skill_barbarian_cleave','skill_barbarian_weaponthrow','skill_barbarian_frenzy','skill_barbarian_bash') WHERE c.class=1 AND a.affix_id='skill_legs';
